function parseDate(value) {
  const s = String(value || "").trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);      // 2026-09-24
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{2})-(\d{2})-(\d{4})$/);          // 24-09-2026
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  return null;
}

const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 7);

const rows = $input.all()
  .map(i => i.json)
  .filter(r => {
    const d = parseDate(r.Date);
    return d && d > cutoff;
  });

if (rows.length === 0) {
  return [{ json: { message: "📊 Weekly feedback digest\nNo new feedback this week." } }];
}

const ratings = rows.map(r => Number(r.Rating));
const avg = ratings.reduce((a, b) => a + b, 0) / ratings.length;

const counts = {};
for (const r of rows) {
  const c = r.Category || "none";
  counts[c] = (counts[c] || 0) + 1;
}
const categoryLines = Object.entries(counts)
  .map(([c, n]) => `${c}: ${n}`)
  .join("\n");

const lowest = rows
  .filter(r => r.Feedback)
  .sort((a, b) => Number(a.Rating) - Number(b.Rating))
  .slice(0, 3)
  .map(r => `(${r.Rating}/5) ${r.Summary || r.Feedback}`)
  .join("\n");

const message =
  `📊 Weekly feedback digest\n` +
  `Responses: ${rows.length}\n` +
  `Average rating: ${avg.toFixed(1)}/5\n\n` +
  `By category:\n${categoryLines}\n\n` +
  `Lowest-rated comments:\n${lowest || "none"}`;

return [{ json: { message } }];
